trait MetadataFieldDeclarationIndexTestExt {
    fn with_table(self, reference: &str, declared: MetadataTableStandardAttributes) -> Self;
    fn with_constant(self, uuid: &str, declared: MetadataConstantDeclaration) -> Self;
    fn with_common_attribute(self, name: &str, content: MetadataCommonAttributeContent) -> Self;
    fn with_password_field(self, table: &str, field: &str) -> Self;
    fn with_data_fields(self, table: &str, fields: &[&str]) -> Self;
    fn with_field_reference_owner(self, table: &str, field: &str, owner: &str) -> Self;
    fn with_document_journal_documents(self, journal: &str, documents: &[&str]) -> Self;
}

impl MetadataFieldDeclarationIndexTestExt for MetadataFieldDeclarationIndex {
    fn with_table(mut self, reference: &str, declared: MetadataTableStandardAttributes) -> Self {
        self.tables.insert(reference.to_string(), declared);
        self
    }

    fn with_constant(mut self, uuid: &str, declared: MetadataConstantDeclaration) -> Self {
        self.constants.insert(uuid.to_string(), declared);
        self
    }

    fn with_common_attribute(
        mut self,
        name: &str,
        content: MetadataCommonAttributeContent,
    ) -> Self {
        self.common_attributes.insert(name.to_string(), content);
        self
    }

    fn with_password_field(mut self, table: &str, field: &str) -> Self {
        self.password_fields
            .entry(table.to_string())
            .or_default()
            .insert(field.to_lowercase());
        self
    }

    fn with_data_fields(mut self, table: &str, fields: &[&str]) -> Self {
        self.data_fields.insert(
            table.to_string(),
            fields.iter().map(|field| field.to_lowercase()).collect(),
        );
        self
    }

    fn with_field_reference_owner(mut self, table: &str, field: &str, owner: &str) -> Self {
        self.field_types
            .entry(table.to_string())
            .or_default()
            .insert(field.to_lowercase(), owner.to_string());
        self
    }

    fn with_document_journal_documents(mut self, journal: &str, documents: &[&str]) -> Self {
        self.document_journal_documents.insert(
            journal.to_string(),
            documents
                .iter()
                .map(|document| (*document).to_string())
                .collect(),
        );
        self
    }
}

trait MetadataTableStandardAttributesTestExt {
    fn with_code_length(self, code_length: u32) -> Self;
    fn with_owners(self, owned: bool) -> Self;
}

impl MetadataTableStandardAttributesTestExt for MetadataTableStandardAttributes {
    fn with_code_length(mut self, code_length: u32) -> Self {
        self.code_length = Some(code_length);
        self
    }

    fn with_owners(mut self, owned: bool) -> Self {
        self.owned = Some(owned);
        self
    }
}

trait MetadataCommonAttributeContentTestExt {
    fn declared(auto_use: bool, content: &[(&str, bool)]) -> Self;
}

impl MetadataCommonAttributeContentTestExt for MetadataCommonAttributeContent {
    fn declared(auto_use: bool, content: &[(&str, bool)]) -> Self {
        Self {
            auto_use,
            content: content
                .iter()
                .map(|(table, used)| ((*table).to_string(), *used))
                .collect(),
        }
    }
}

#[test]
fn form_absent_metadata_physical_path_defers_platform_grammar_families() {
    let object_refs = BTreeMap::new();
    assert_eq!(
        resolve_form_absent_metadata_physical_data_path(
            "{2,{1},{0,11111111-1111-4111-8111-111111111111}}",
            &object_refs,
        )
        .as_deref(),
        Some("1/0:11111111-1111-4111-8111-111111111111")
    );

    for family in [
        "5bdad865-f2c5-434b-8041-ba4aad3b6687",
        "e67e2953-cebe-4d97-bb93-12b17e6384f8",
        "1ab44b24-3315-40a9-b495-f1f1227ac205",
        "f77758c9-9fcd-490f-9bbd-1e446541f536",
        "91162600-3161-4326-89a0-4a7cecd5092a",
    ] {
        assert_eq!(
            resolve_form_absent_metadata_physical_data_path(
                &format!("{{2,{{1}},{{0,{family}}}}}"),
                &object_refs,
            ),
            None,
            "platform grammar family {family} must stay with its logical resolver"
        );
    }
}

/// Slots 3 upwards name the register's master dimensions positionally, in
/// declaration order.
///
/// The test this replaces asserted that slots 3, 4 and 5 all name the *same*
/// dimension, a layout the platform never writes: the whole point of the slot is
/// that it selects a different one. Measured over 1C:УТ 11.5.27.75, the five
/// slots occur 111, 26, 13, 5 and 1 times and pick the first through fifth
/// master dimension respectively.
#[test]
fn form_navigation_panel_slots_from_three_name_master_dimensions_in_order() {
    let register_uuid = "11111111-1111-4111-8111-111111111111".to_string();
    let object_refs = BTreeMap::from([(
        register_uuid.clone(),
        "InformationRegister.RegisterProbe".to_string(),
    )]);
    let master_dimensions = BTreeMap::from([(
        register_uuid.clone(),
        ["Склад", "Помещение", "Номенклатура", "Серия", "Упаковка"]
            .into_iter()
            .map(str::to_string)
            .collect::<Vec<_>>(),
    )]);

    for (kind, dimension) in [
        ("3", "Склад"),
        ("4", "Помещение"),
        ("5", "Номенклатура"),
        ("6", "Серия"),
        ("7", "Упаковка"),
    ] {
        assert_eq!(
            parse_form_command_interface_command_for_test(
                &format!("{{{kind},{register_uuid}}}"),
                &object_refs,
                &BTreeMap::new(),
                &master_dimensions,
                "Catalog.Products",
            ),
            Some(format!(
                "InformationRegister.RegisterProbe.StandardCommand.OpenByValue.{dimension}"
            )),
            "kind {kind}"
        );
    }
}

/// A slot past the last master dimension keeps its raw command identifier
/// rather than falling back to the nearest one.
#[test]
fn form_navigation_panel_register_open_by_value_refuses_slot_past_last_master_dimension() {
    let register_uuid = "22222222-2222-4222-8222-222222222222".to_string();
    let object_refs = BTreeMap::from([(
        register_uuid.clone(),
        "InformationRegister.RegisterProbe".to_string(),
    )]);
    let master_dimensions = BTreeMap::from([(
        register_uuid.clone(),
        vec!["Организация".to_string(), "Склад".to_string()],
    )]);
    assert_eq!(
        parse_form_command_interface_command_for_test(
            &format!("{{4,{register_uuid}}}"),
            &object_refs,
            &BTreeMap::new(),
            &master_dimensions,
            "Catalog.Products",
        ),
        Some("InformationRegister.RegisterProbe.StandardCommand.OpenByValue.Склад".to_string())
    );
    assert_eq!(
        parse_form_command_interface_command_for_test(
            &format!("{{5,{register_uuid}}}"),
            &object_refs,
            &BTreeMap::new(),
            &master_dimensions,
            "Catalog.Products",
        ),
        Some(format!("5:{register_uuid}"))
    );
}

/// A non-master dimension is never named, however well it matches the form's
/// owner: all 156 occurrences in the corpus name a master dimension.
#[test]
fn form_navigation_panel_register_open_by_value_ignores_non_master_dimensions() {
    let register_uuid = "12121212-1212-4212-8212-121212121212".to_string();
    let object_refs = BTreeMap::from([(
        register_uuid.clone(),
        "InformationRegister.RegisterProbe".to_string(),
    )]);
    let field_refs = BTreeMap::from([(
        register_uuid.clone(),
        vec![InformationRegisterFieldReference {
            field_reference: "InformationRegister.RegisterProbe.Dimension.Плательщик".to_string(),
            value_owner_references: BTreeSet::from(["Catalog.Products".to_string()]),
        }],
    )]);
    let master_dimensions =
        BTreeMap::from([(register_uuid.clone(), vec!["Получатель".to_string()])]);
    assert_eq!(
        parse_form_command_interface_command_for_test(
            &format!("{{3,{register_uuid}}}"),
            &object_refs,
            &field_refs,
            &master_dimensions,
            "Catalog.Products",
        ),
        Some(
            "InformationRegister.RegisterProbe.StandardCommand.OpenByValue.Получатель".to_string()
        )
    );
}

