#[test]
fn extracts_form_server_state_inner_xml() {
    let xml = r#"junk<?xml version="1.0" encoding="UTF-8"?>
<UniversalListServerOnlyState xmlns="" xmlns:xs="http://www.w3.org/2001/XMLSchema" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
	<Field xmlns:dcssch="http://v8.1c.ru/8.1/data-composition-system/schema" xsi:type="dcssch:DataSetFieldField">
		<dcssch:dataPath>Дата</dcssch:dataPath>
		<dcssch:field>Дата</dcssch:field>
	</Field>
	<Parameter xmlns:dcssch="http://v8.1c.ru/8.1/data-composition-system/schema" xsi:type="dcssch:Parameter">
		<dcssch:name>ДатаАктуальности</dcssch:name>
	</Parameter>
	<Field xmlns:dcssch="http://v8.1c.ru/8.1/data-composition-system/schema" xsi:type="dcssch:DataSetFieldField">
		<dcssch:valueType>
			<Type xmlns="http://v8.1c.ru/8.1/data/core">xs:string</Type>
			<TypeId xmlns="http://v8.1c.ru/8.1/data/core">11111111-1111-4111-8111-111111111111</TypeId>
		</dcssch:valueType>
	</Field>
</UniversalListServerOnlyState>"#;

    let inner = extract_form_server_state_inner_xml(xml).expect("server state inner xml");

    assert!(inner.contains(r#"<Field xsi:type="dcssch:DataSetFieldField">"#));
    assert!(inner.contains("<dcssch:dataPath>Дата</dcssch:dataPath>"));
    assert!(inner.contains("<Parameter>"), "{inner}");
    assert!(inner.contains("<dcssch:name>ДатаАктуальности</dcssch:name>"));
    assert!(inner.contains("<v8:Type>xs:string</v8:Type>"), "{inner}");
    assert!(
        inner.contains("<v8:TypeId>11111111-1111-4111-8111-111111111111</v8:TypeId>"),
        "{inner}"
    );
    assert!(!inner.contains("<TypeId xmlns="), "{inner}");
}

fn encode_form_server_state_chunks_for_test(chunks: &[&[u8]]) -> Vec<u8> {
    let mut encoded = vec![0x41, 0xC1];
    for chunk in chunks {
        if chunk.len() <= usize::from(u8::MAX) {
            encoded.extend_from_slice(&[0x9A, chunk.len() as u8]);
        } else {
            let chunk_len = u16::try_from(chunk.len()).expect("test chunk fits u16");
            encoded.push(0x9B);
            encoded.extend_from_slice(&chunk_len.to_le_bytes());
        }
        encoded.extend_from_slice(chunk);
    }
    encoded.extend_from_slice(b"  ");
    encoded
}

fn form_server_state_field_for_test(encoded: &[u8]) -> String {
    format!(r#"{{"S","{}"}}"#, encode_base64_for_test(encoded))
}

#[test]
fn decodes_and_extracts_short_form_server_state_chunk_stream() {
    let payload = concat!(
        "\u{feff}<UniversalListServerOnlyState>",
        "<Field><dcssch:dataPath>Дата</dcssch:dataPath></Field>",
        "</UniversalListServerOnlyState>"
    )
    .as_bytes();
    let encoded = encode_form_server_state_chunks_for_test(&[&payload[..2], &payload[2..]]);

    assert_eq!(
        decode_form_server_state_chunks(&encoded).as_deref(),
        Some(payload)
    );
    let inner = parse_form_server_state_xml(&form_server_state_field_for_test(&encoded))
        .expect("server state inner xml");
    assert!(
        inner.contains("<dcssch:dataPath>Дата</dcssch:dataPath>"),
        "{inner}"
    );
}

#[test]
fn decodes_form_server_state_chunks_split_inside_utf8_character() {
    let mut payload = b"\xEF\xBB\xBF<UniversalListServerOnlyState xmlns:dcssch=\"http://v8.1c.ru/8.1/data-composition-system/schema\"><Field><dcssch:dataPath>".to_vec();
    let split_at = 2 + 32_768;
    let multibyte_start = split_at - 1;
    payload.resize(multibyte_start, b'a');
    payload.extend_from_slice("Ж".as_bytes());
    payload.extend_from_slice(b"</dcssch:dataPath></Field></UniversalListServerOnlyState>");
    assert_eq!(payload[multibyte_start], 0xD0);
    assert_eq!(payload[split_at], 0x96);

    let encoded = encode_form_server_state_chunks_for_test(&[
        &payload[..2],
        &payload[2..split_at],
        &payload[split_at..],
    ]);

    assert_eq!(
        decode_form_server_state_chunks(&encoded).as_deref(),
        Some(payload.as_slice())
    );
    let inner = parse_form_server_state_xml(&form_server_state_field_for_test(&encoded))
        .expect("UTF-8 is decoded after joining chunks");
    assert!(inner.contains("Ж</dcssch:dataPath>"), "{inner}");
}

#[test]
fn rejects_malformed_form_server_state_chunk_streams() {
    let malformed = [
        ("bad magic", vec![0x41, 0xC0, 0x20, 0x20]),
        ("missing terminator", vec![0x41, 0xC1]),
        (
            "unknown 9c tag",
            vec![0x41, 0xC1, 0x9C, 0, 0, 0, 0, 0x20, 0x20],
        ),
        ("truncated 9b length", vec![0x41, 0xC1, 0x9B, 1]),
        ("truncated chunk", vec![0x41, 0xC1, 0x9A, 3, b'a']),
        ("trailing byte", vec![0x41, 0xC1, 0x20, 0x20, 0]),
    ];
    for (case, encoded) in malformed {
        assert!(
            decode_form_server_state_chunks(&encoded).is_none(),
            "{case}"
        );
    }

    let oversized = encode_form_server_state_chunks_for_test(&[b"abc".as_slice()]);
    assert!(
        decode_form_server_state_chunks_with_limit(&oversized, 2).is_none(),
        "bounded decoder must reject output over its limit"
    );
}

#[test]
fn rejects_invalid_utf8_form_server_state_chunk_stream() {
    let encoded = encode_form_server_state_chunks_for_test(&[&[0xFF]]);
    assert_eq!(decode_form_server_state_chunks(&encoded), Some(vec![0xFF]));
    assert!(parse_form_server_state_xml(&form_server_state_field_for_test(&encoded)).is_none());
}

/// Locates the raw `"ServerState",{"S","<base64>"}` property-bag value
/// within a retained (already UTF-8 decoded) `form-body-unpacked.bin`
/// fixture, returning the `{"S","<base64>"}` slice on its own -- the same
/// shape `parse_form_dynamic_list_settings_with_dcs_type_index` passes as
/// `window[1]` when it encounters the `"ServerState"` key in the property
/// bag.
fn locate_form_server_state_raw_field(form_body_unpacked: &str) -> &str {
    let key_start = form_body_unpacked
        .find("\"ServerState\"")
        .expect("retained fixture has a ServerState property key");
    let brace_offset = form_body_unpacked[key_start..]
        .find('{')
        .expect("ServerState value opens with a brace");
    &form_body_unpacked[key_start + brace_offset..]
}

/// Extracts the exact raw (post-base64-decode, pre-chunk-decode) storage
/// fragment bytes for `ServerState` from a retained fixture -- the bytes
/// [`decode_form_server_state_chunks`] itself consumes.
fn form_server_state_raw_storage_fragment(form_body_unpacked: &str) -> Vec<u8> {
    let field = locate_form_server_state_raw_field(form_body_unpacked);
    let payload =
        parse_form_setting_string(field).expect("ServerState value parses as a 1C string");
    decode_base64_mime(&payload).expect("ServerState payload is valid base64")
}

fn assert_dcs_form_server_state_corpus_round_trips(
    form_body_unpacked_b64: &str,
    server_state_decoded_b64: &str,
) {
    let form_body_unpacked = decode_base64_mime(form_body_unpacked_b64)
        .expect("retained form-body-unpacked fixture is valid base64");
    let form_body_unpacked =
        String::from_utf8(form_body_unpacked).expect("retained form body is UTF-8 text");
    let expected_decoded = decode_base64_mime(server_state_decoded_b64)
        .expect("retained server-state-decoded fixture is valid base64");

    let raw_fragment = form_server_state_raw_storage_fragment(&form_body_unpacked);

    // Decode direction: the existing chunk decoder, applied to the exact raw
    // storage fragment extracted from the retained fixture, reproduces the
    // retained decoded envelope byte-for-byte.
    let (decoded, chunk_lengths) =
        decode_form_server_state_chunks_with_boundaries(&raw_fragment, 1_048_576)
            .expect("evidenced ServerState fragment decodes");
    assert_eq!(decoded, expected_decoded);

    // The policy-bound classifier recognizes this exact content as the one
    // platform-proven empty envelope.
    let field = locate_form_server_state_raw_field(&form_body_unpacked);
    assert_eq!(
        parse_form_server_state_envelope(field),
        Some(FormServerStateEnvelope::Empty)
    );

    // Encode direction: re-encoding the decoded payload using the platform's
    // own chunk-length sequence (discovered, not guessed) reproduces the
    // retained raw storage fragment byte-for-byte.
    let re_encoded = encode_form_server_state_chunks(&decoded, &chunk_lengths)
        .expect("re-encoding the evidenced payload with its own boundaries succeeds");
    assert_eq!(re_encoded, raw_fragment);
}

#[test]
fn dcs_form_dynamic_list_server_state_corpus_round_trips_against_retained_evidence() {
    const FORM_BODY_UNPACKED_B64: &str = include_str!(
        "../../../../tests/fixtures/native-evidence/8.3.27.2214/dcs-form-dynamic-list-server-state/form-body-unpacked.bin.b64"
    );
    const SERVER_STATE_DECODED_B64: &str = include_str!(
        "../../../../tests/fixtures/native-evidence/8.3.27.2214/dcs-form-dynamic-list-server-state/server-state-decoded.xml.b64"
    );
    assert_dcs_form_server_state_corpus_round_trips(
        FORM_BODY_UNPACKED_B64,
        SERVER_STATE_DECODED_B64,
    );
}

