#[test]
fn input_field_option_tail_reads_its_own_slots() {
    let mut options = vec!["0"; 66];
    options[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::MarkNegatives.index()] = "1";
    options[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::ChoiceListHeight.index()] = "20";
    options[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::AutoChoiceIncomplete.index()] =
        "0";
    options[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::TypeDomainEnabled.index()] = "0";
    options[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::HeightControlVariant.index()] =
        "2";

    assert_eq!(
        parse_form_option_mark_negatives(
            &options,
            ibcmd_form_schema::FormInputFieldExtendedOptionSlot::MarkNegatives.index()
        ),
        Some(true)
    );
    assert_eq!(
        parse_form_input_field_choice_list_height(Some(&options)).as_deref(),
        Some("20")
    );
    assert_eq!(
        parse_form_input_field_auto_choice_incomplete(Some(&options)),
        Some(false)
    );
    assert_eq!(
        parse_form_input_field_type_domain_enabled(Some(&options)),
        Some(false)
    );
    assert_eq!(
        parse_form_input_field_height_control_variant(Some(&options)),
        Some("UseContentHeight")
    );

    // The codes the platform writes when it emits nothing at all.
    let mut quiet = vec!["0"; 66];
    quiet[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::MarkNegatives.index()] = "2";
    quiet[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::AutoChoiceIncomplete.index()] = "2";
    quiet[ibcmd_form_schema::FormInputFieldExtendedOptionSlot::TypeDomainEnabled.index()] = "1";
    assert_eq!(
        parse_form_option_mark_negatives(
            &quiet,
            ibcmd_form_schema::FormInputFieldExtendedOptionSlot::MarkNegatives.index()
        ),
        None
    );
    assert_eq!(
        parse_form_input_field_choice_list_height(Some(&quiet)),
        None
    );
    assert_eq!(
        parse_form_input_field_auto_choice_incomplete(Some(&quiet)),
        None
    );
    assert_eq!(
        parse_form_input_field_type_domain_enabled(Some(&quiet)),
        None
    );
    assert_eq!(
        parse_form_input_field_height_control_variant(Some(&quiet)),
        None
    );
}

