#[test]
fn additional_columns_metadata_reference_precedes_and_guards_child_binding() {
    let metadata_uuid = "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa";
    let attributes = vec![FormAttribute {
        design_time_settings: None,
        view_rights: None,
        edit_rights: None,
        id: "1".to_string(),
        name: "Object".to_string(),
        title: Vec::new(),
        value_types: vec![ConstantValueType::Reference {
            reference: "cfg:DocumentObject.Invoice".to_string(),
        }],
        exact_single_type_uuid: None,
        explicit_empty_type: false,
        columns: Vec::new(),
        additional_columns: Vec::new(),
        main_attribute: true,
        saved_data: false,
        fill_check: None,
        save_fields: Vec::new(),
        use_always: Vec::new(),
        functional_options: Vec::new(),
        settings: None,
        spreadsheet_document_settings: None,
        type_description_settings: None,
        unresolvable_field_item_ids: BTreeSet::new(),
        invalid_nested_field_item_ids: BTreeSet::new(),
        field_item_twins: BTreeMap::new(),
    }];
    let mut indexes = FormChildItemIndexes::default();
    indexes.insert_owner_scoped_table_path_for_test(
        "1",
        &format!("0|{metadata_uuid}"),
        "Object.ChildFallback",
    );
    indexes.insert_owner_scoped_table_path_for_test(
        "1",
        "0|not-a-uuid",
        "Object.MalformedFallback",
    );
    let group = |uuid: &str| {
        format!(
            r#"{{0,{{2,{{1}},{{0,{uuid}}}}},1,{{5,1,0,"Selected",{{1,0}},{{"Pattern",{{"B"}}}},{{0,{{0,{{"B",1}},0}}}},{{0,{{0,{{"B",1}},0}}}},{{0,0}},0}}}}"#
        )
    };

    assert_eq!(
        parse_form_attribute_additional_columns_group(
            &group(metadata_uuid),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &indexes,
        )
        .unwrap()
        .table,
        "Object.ChildFallback",
        "a valid UUID absent from object_refs may use the unique child binding"
    );
    assert_eq!(
        parse_form_attribute_additional_columns_group(
            &group(metadata_uuid),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::from([(
                metadata_uuid.to_string(),
                "Document.Invoice.TabularSection.Lines".to_string(),
            )]),
            &indexes,
        )
        .unwrap()
        .table,
        "Object.Lines",
        "an indexed valid metadata route must take precedence over the child path"
    );

    for reference in [
        "Document.OtherInvoice.TabularSection.Lines",
        "Document.Invoice.Command.Lines",
    ] {
        assert!(
            parse_form_attribute_additional_columns_group(
                &group(metadata_uuid),
                &attributes,
                &BTreeMap::new(),
                &BTreeMap::from([(metadata_uuid.to_string(), reference.to_string())]),
                &indexes,
            )
            .is_none(),
            "an indexed invalid metadata reference must not fall back to a child path: {reference}"
        );
    }
    assert!(
        parse_form_attribute_additional_columns_group(
            &group("not-a-uuid"),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &indexes,
        )
        .is_none(),
        "a malformed UUID must be rejected even when a child binding exists"
    );
}

#[test]
fn resolves_additional_columns_binding_per_owner_and_rejects_collisions() {
    let attribute = |id: &str, name: &str| FormAttribute {
        design_time_settings: None,
        view_rights: None,
        edit_rights: None,
        id: id.to_string(),
        name: name.to_string(),
        title: Vec::new(),
        value_types: Vec::new(),
        exact_single_type_uuid: None,
        explicit_empty_type: false,
        columns: Vec::new(),
        additional_columns: Vec::new(),
        main_attribute: true,
        saved_data: false,
        fill_check: None,
        save_fields: Vec::new(),
        use_always: Vec::new(),
        functional_options: Vec::new(),
        settings: None,
        spreadsheet_document_settings: None,
        type_description_settings: None,
        unresolvable_field_item_ids: BTreeSet::new(),
        invalid_nested_field_item_ids: BTreeSet::new(),
        field_item_twins: BTreeMap::new(),
    };
    let attributes = vec![attribute("1", "ОбъектА"), attribute("2", "ОбъектБ")];
    let binding_key = "0|b5f6377f-aec6-4864-9ae0-7e034769a4ca";
    let group = |attribute_id: &str| {
        format!(
            r#"{{0,{{2,{{{attribute_id}}},{{0,b5f6377f-aec6-4864-9ae0-7e034769a4ca}}}},1,{{5,1,0,"Выбран",{{1,0}},{{"Pattern",{{"B"}}}},{{0,{{0,{{"B",1}},0}}}},{{0,{{0,{{"B",1}},0}}}},{{0,0}},0}}}}"#
        )
    };

    let mut indexes = FormChildItemIndexes::default();
    indexes.bound_table_path_by_binding_key.insert(
        binding_key.to_string(),
        "ОбъектБ.ГлобальноПерезаписанныйПуть".to_string(),
    );
    indexes.insert_owner_scoped_table_path_for_test("1", binding_key, "ОбъектА.Товары");
    indexes.insert_owner_scoped_table_path_for_test("2", binding_key, "ОбъектБ.Строки");

    assert_eq!(
        parse_form_attribute_additional_columns_group(
            &group("1"),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &indexes,
        )
        .unwrap()
        .table,
        "ОбъектА.Товары"
    );
    assert_eq!(
        parse_form_attribute_additional_columns_group(
            &group("2"),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &indexes,
        )
        .unwrap()
        .table,
        "ОбъектБ.Строки"
    );

    let mut global_only = FormChildItemIndexes::default();
    global_only.bound_table_path_by_binding_key.insert(
        binding_key.to_string(),
        "ОбъектА.НедоказанныйПуть".to_string(),
    );
    assert!(
        parse_form_attribute_additional_columns_group(
            &group("1"),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &global_only,
        )
        .is_none(),
        "a global binding key must not prove ownership"
    );

    indexes.insert_owner_scoped_table_path_for_test("1", binding_key, "ОбъектА.ДругаяТаблица");
    assert!(
        parse_form_attribute_additional_columns_group(
            &group("1"),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &indexes,
        )
        .is_none(),
        "conflicting paths for the same owner/key must remain ambiguous"
    );
    assert_eq!(
        parse_form_attribute_additional_columns_group(
            &group("2"),
            &attributes,
            &BTreeMap::new(),
            &BTreeMap::new(),
            &indexes,
        )
        .unwrap()
        .table,
        "ОбъектБ.Строки",
        "a collision for another owner must not poison this owner"
    );
}

