#[test]
fn form_document_properties_trail_command_set_and_precede_show_title() {
    // Native document forms emit `CommandSet` then the `AutoTime`/
    // `UsePostingMode`/`RepostOnWrite` trio (238 co-occurrences), and place
    // `ShowTitle` ahead of `UseForFoldersAndItems` (1).  `ShowTitle` itself is
    // never observed beside the trio in any of the eight native stand trees,
    // and it precedes `CollapseItemsByImportanceVariant` (3), which in turn
    // precedes the trio (2 each) -- so the writer puts the two window switches
    // ahead of the trio and this synthetic form sees `ShowTitle` there.
    let properties = FormBodyProperties {
        scale: None,
        command_set_excluded_commands: vec!["Form.Command"],
        scaling_mode: Some("Normal"),
        command_bar_location: Some("Top"),
        auto_time: Some("DontUse"),
        use_posting_mode: Some("RegularPosting"),
        repost_on_write: Some(true),
        show_title: Some(false),
        use_for_folders_and_items: Some("Items"),
        ..FormBodyProperties::default()
    };
    let xml = format_form_body_xml(
        &properties,
        None,
        &[],
        &[],
        &[],
        &FormAttributesSection::default(),
        &[],
        &[],
        &None,
    )
    .unwrap();
    assert_xml_order(
        &xml,
        &[
            "<CommandBarLocation>Top</CommandBarLocation>",
            "<ScalingMode>Normal</ScalingMode>",
            "<CommandSet>",
            "<ShowTitle>false</ShowTitle>",
            "<AutoTime>DontUse</AutoTime>",
            "<UsePostingMode>RegularPosting</UsePostingMode>",
            "<RepostOnWrite>true</RepostOnWrite>",
            "<UseForFoldersAndItems>Items</UseForFoldersAndItems>",
        ],
    );
}

/// Builds a minimal managed-form `InputField` layout item carrying `binding`
/// in the bound-data slot, in the shape UT 11.5.27.75 writes for a plain field.
fn data_path_input_field(id: &str, name: &str, binding: &str) -> String {
    format!(
        r#"{{37,{{{id},02023637-7868-4a5f-8576-835a76e0c9ba}},0,0,0,2,"{name}",1,0,{{1,0}},{{1,0}},{binding},{{0}},1,0,2,0,2,{{1,0}},{{1,0}},1,1,0,3,0,3,2,3,0}}"#
    )
}

fn data_path_table_item(id: &str, name: &str, binding: &str) -> String {
    format!(
        r#"{{73,{{{id},02023637-7868-4a5f-8576-835a76e0c9ba}},0,1,0,"{name}",0,0,1,{{1,0}},0,{binding},0,0,0,0,0,0,0,0,0,6,0,0,1,0,1,0,0,1,2}}"#
    )
}

