/// A dynamic list's `DefaultPicture` carries the `~` marker exactly when the
/// declared main table cannot hold it.
///
/// Evidence: UT 11.5.27.75 spells out 1 587 row-picture `…DefaultPicture`
/// paths. All 55 lists that declare no main table carry `~`, and so do all 6
/// whose declared main table is an `Enum` -- for example
/// `Enums/СтатусыПриглашений/Forms/ФормаВыбора`, whose `Список` declares
/// `<MainTable>Enum.СтатусыПриглашений</MainTable>` and for which the platform
/// writes `<RowPictureDataPath>~Список.DefaultPicture</RowPictureDataPath>`.
/// The remaining 1 526, across nine other main-table families, carry none.
#[test]
fn marks_a_default_picture_the_declared_main_table_cannot_hold() {
    let owner_with = |main_table: Option<&str>, dynamic_list: bool, manual_query: bool| {
        let mut attribute = data_path_form_attribute("1", "Список", None);
        if dynamic_list {
            let mut settings = data_path_dynamic_list_settings(Vec::new());
            settings.main_table = main_table.map(ToOwned::to_owned);
            settings.manual_query = manual_query;
            attribute.settings = Some(settings);
        }
        form_attribute_metadata_owner(&attribute)
    };
    let owner_for =
        |main_table: Option<&str>, dynamic_list: bool| owner_with(main_table, dynamic_list, true);
    // An Enum list under the platform's own query is marked like any other
    // (1C:Документооборот's `Enums/СтатусыПриглашений` list forms under
    // compatibility 8.3.21 and 8.3.24); under 8.3.17 the platform writes them
    // unmarked, which `with_no_main_table_default_picture_unmarked` restores.
    assert!(form_dynamic_list_default_picture_is_out_of_main_table(
        &owner_with(Some("Enum.СтатусыПриглашений"), true, false)
    ));

    for (main_table, expected) in [
        (None, true),
        (Some("Enum.СтатусыПриглашений"), true),
        (Some("Catalog.Пользователи"), false),
        (Some("Document.ЗаявкаНаОбеспечение"), false),
        (Some("InformationRegister.ЦеныНоменклатуры"), false),
    ] {
        assert_eq!(
            form_dynamic_list_default_picture_is_out_of_main_table(&owner_for(main_table, true)),
            expected,
            "{main_table:?}"
        );
    }

    // An attribute that is not a dynamic list has no such field at all.
    assert!(!form_dynamic_list_default_picture_is_out_of_main_table(
        &owner_for(None, false)
    ));
}

/// A chain segment that names a metadata field reaches a value of that field's
/// *declared* type, and a following marker reads that type's standard
/// attributes -- exactly as it does after a declared form column.
///
/// Evidence: UT 11.5.27.75.
/// `Catalogs/БанковскиеСчетаКонтрагентов/Forms/ФормаЭлемента` carries
/// `{3,{1},{0,9e7b0920-…},{-2}}` and `{3,{1},{0,9e7b0920-…},{-3}}` on the same
/// field, which is `Catalog.БанковскиеСчетаКонтрагентов.Attribute.Банк`
/// declared `cfg:CatalogRef.КлассификаторБанков`; the platform writes
/// `<DataPath>Объект.Банк.Code</DataPath>` and
/// `<DataPath>Объект.Банк.Description</DataPath>`.
/// `Documents/СчетФактураПолученныйАванс/Forms/ФормаДокумента` carries
/// `{3,{1},{0,f9c452ce-…},{-2}}` on a field declared
/// `cfg:DocumentRef.СчетФактураПолученныйАванс` and the platform writes
/// `Объект.СчетФактураОснование.Number`, while
/// `Documents/СчетФактураВыданныйАванс/Forms/ФормаДокумента` carries `{-3}` in
/// the same place and writes `Объект.СчетФактураОснование.Date`. The same `-2`
/// therefore writes `Code` under one declared type and `Number` under another,
/// so the marker alone establishes nothing and the declared type decides.
#[test]
fn dereferences_a_metadata_field_through_its_declared_type() {
    let bank_uuid = "9e7b0920-3d4f-481a-9dce-a789a4e9ef73";
    let invoice_uuid = "f9c452ce-e7db-4048-9486-d5a5d219135d";
    let attributes = vec![data_path_form_attribute("1", "Объект", None)];
    let names = form_attribute_metadata_owners_by_id(&attributes);
    let object_refs = BTreeMap::from([
        (
            bank_uuid.to_string(),
            "Catalog.БанковскиеСчетаКонтрагентов.Attribute.Банк".to_string(),
        ),
        (
            invoice_uuid.to_string(),
            "Document.СчетФактураПолученныйАванс.Attribute.СчетФактураОснование".to_string(),
        ),
    ]);
    let field_types = BTreeMap::from([
        (
            bank_uuid.to_string(),
            "cfg:CatalogRef.КлассификаторБанков".to_string(),
        ),
        (
            invoice_uuid.to_string(),
            "cfg:DocumentRef.СчетФактураПолученныйАванс".to_string(),
        ),
    ]);
    let indexes = chain_walk_indexes_with_metadata_field_types(&attributes, field_types);

    for (uuid, marker, expected) in [
        (bank_uuid, "-2", "Объект.Банк.Code"),
        (bank_uuid, "-3", "Объект.Банк.Description"),
        (invoice_uuid, "-2", "Объект.СчетФактураОснование.Number"),
        (invoice_uuid, "-3", "Объект.СчетФактураОснование.Date"),
    ] {
        assert_eq!(
            resolve_form_bound_chain_member_path(
                &format!("{{3,{{1}},{{0,{uuid}}},{{{marker}}}}}"),
                &names,
                indexes.owner_scoped_bindings_for_test(),
                &object_refs,
                false,
            )
            .as_deref(),
            Some(expected),
            "{uuid} {marker}"
        );
    }

    // A marker the declared type's table does not list stays fail-closed rather
    // than borrowing a name from a table that belongs to another family.
    for marker in ["-4", "-8", "-9"] {
        assert_eq!(
            resolve_form_bound_chain_member_path(
                &format!("{{3,{{1}},{{0,{bank_uuid}}},{{{marker}}}}}"),
                &names,
                indexes.owner_scoped_bindings_for_test(),
                &object_refs,
                false,
            ),
            None,
            "marker {marker}"
        );
    }

    // Without the declared type the same slot resolves to nothing at all: the
    // rule is a function of that type, and a route without it has no answer to
    // guess at. A field declaring several types, or none, is absent from the
    // index for the same reason and lands here too.
    let starved = chain_walk_indexes(&attributes);
    for marker in ["-2", "-3"] {
        assert_eq!(
            resolve_form_bound_chain_member_path(
                &format!("{{3,{{1}},{{0,{bank_uuid}}},{{{marker}}}}}"),
                &names,
                starved.owner_scoped_bindings_for_test(),
                &object_refs,
                false,
            ),
            None,
            "starved {marker}"
        );
    }
}

/// The first member of a chain stands on the root attribute's own value, so
/// the attribute's declared type names a marker there -- at any chain length,
/// not only on the two-segment chain a route of its own used to admit.
///
/// Evidence: Документооборот КОРП 3.0.21.3
/// `Catalogs/СообщенияОбсуждений/Forms/ФормаЭлемента`, InputField
/// `РодительТекстСообщения`, which carries `{3,{1},{-4},{0,7e0d1815-…}}`
/// against the `Объект` attribute of exact type
/// `cfg:CatalogObject.СообщенияОбсуждений`: `-4` is that object's `Parent` and
/// `7e0d1815-…` is `Catalog.СообщенияОбсуждений.Attribute.ТекстСообщения`. The
/// platform writes `<DataPath>Объект.Parent.ТекстСообщения</DataPath>`; the
/// walker used to refuse the marker outright and a looser route answered
/// `Объект.ТекстСообщения`.
#[test]
fn dereferences_the_root_attribute_through_its_own_standard_attributes() {
    let text_uuid = "7e0d1815-9f65-441c-8357-67df2bbf35ab";
    let mut attribute = data_path_form_attribute("1", "Объект", None);
    attribute.value_types = vec![ConstantValueType::Reference {
        reference: "cfg:CatalogObject.СообщенияОбсуждений".to_string(),
    }];
    let attributes = vec![attribute];
    let indexes = chain_walk_indexes(&attributes);
    let names = form_attribute_metadata_owners_by_id(&attributes);
    let object_refs = BTreeMap::from([(
        text_uuid.to_string(),
        "Catalog.СообщенияОбсуждений.Attribute.ТекстСообщения".to_string(),
    )]);

    assert_eq!(
        resolve_form_bound_chain_member_path(
            &format!("{{3,{{1}},{{-4}},{{0,{text_uuid}}}}}"),
            &names,
            indexes.owner_scoped_bindings_for_test(),
            &object_refs,
            false,
        )
        .as_deref(),
        Some("Объект.Parent.ТекстСообщения")
    );

    // The two-segment chain the removed route used to answer reads the same
    // declaration through the same walker.
    assert_eq!(
        resolve_form_bound_chain_member_path(
            "{2,{1},{-4}}",
            &names,
            indexes.owner_scoped_bindings_for_test(),
            &object_refs,
            false,
        )
        .as_deref(),
        Some("Объект.Parent")
    );

    // A marker the declared type's table does not list keeps the refusal, and
    // so does a marker that is not in the first member position -- what stands
    // there is not the attribute's own value any more.
    assert_eq!(
        resolve_form_bound_chain_member_path(
            "{2,{1},{-11}}",
            &names,
            indexes.owner_scoped_bindings_for_test(),
            &object_refs,
            false,
        ),
        None
    );
    assert_eq!(
        resolve_form_bound_chain_member_path(
            &format!("{{3,{{1}},{{0,{text_uuid}}},{{-4}}}}"),
            &names,
            indexes.owner_scoped_bindings_for_test(),
            &object_refs,
            false,
        ),
        None
    );
}

